#!/usr/bin/env python3
"""Restore the length-16 21,902-bit witness using Python's standard library.
Data is xz-compressed and base64-encoded for GitHub portability.
Run: python3 lyndon16_restore_witness.py
Then run: python3 lyndon16_verify.py
"""
import base64
import hashlib
import lzma
from pathlib import Path

DATA = """"""
raw = lzma.decompress(base64.b64decode(DATA))
assert hashlib.sha256(raw).hexdigest() == "b9a6e1608ae5461fed79eb7a09c41d1c6517ee2b9d3350a2ca6c92751a28da58"
dest = Path(__file__).resolve().parent / "lyndon16_witness_experiment.txt"
dest.write_bytes(raw)
print("Restored:", dest.name, "bits:", len(raw.strip()))
